document.addEventListener('DOMContentLoaded',()=>{const themeToggleBtn=document.getElementById('theme-toggle');const currentTheme=localStorage.getItem('theme');if(currentTheme==='dark'){document.body.classList.add('dark-theme');}else if(currentTheme==='light'){document.body.classList.remove('dark-theme');}else{const prefersDark=window.matchMedia('(prefers-color-scheme:dark)').matches;if(prefersDark){document.body.classList.add('dark-theme');}}themeToggleBtn.addEventListener('click',()=>{document.body.classList.toggle('dark-theme');let theme='light';if(document.body.classList.contains('dark-theme')){theme='dark';}localStorage.setItem('theme',theme);});const hamburger=document.getElementById('hamburger');const navMenu=document.getElementById('nav-menu');const navLinks=document.querySelectorAll('.nav-link');const toggleMenu=()=>{const isOpen=hamburger.getAttribute('aria-expanded')==='true';hamburger.setAttribute('aria-expanded',!isOpen);navMenu.classList.toggle('open');if(!isOpen){document.body.style.overflow='hidden';}else{document.body.style.overflow='';}};hamburger.addEventListener('click',toggleMenu);navLinks.forEach(link=>{link.addEventListener('click',()=>{hamburger.setAttribute('aria-expanded','false');navMenu.classList.remove('open');document.body.style.overflow='';});});window.addEventListener('resize',()=>{if(window.innerWidth>992){hamburger.setAttribute('aria-expanded','false');navMenu.classList.remove('open');document.body.style.overflow='';}});const header=document.querySelector('header');window.addEventListener('scroll',()=>{if(window.scrollY>50){header.classList.add('nav-scrolled');}else{header.classList.remove('nav-scrolled');}});const sections=document.querySelectorAll('section,footer');window.addEventListener('scroll',()=>{let scrollPos=window.scrollY+120;sections.forEach(section=>{if(section.id&&scrollPos>=section.offsetTop&&scrollPos<section.offsetTop+section.offsetHeight){navLinks.forEach(link=>{link.classList.remove('active');if(link.getAttribute('href')===`#${section.id}`){link.classList.add('active');}});}});});const currentHeatSource=document.getElementById('calc-source');const houseAreaInput=document.getElementById('calc-area');const houseAreaValue=document.getElementById('calc-area-val');const annualSavingsText=document.getElementById('calc-savings');const currentCostText=document.getElementById('calc-current-cost');const hpCostText=document.getElementById('calc-hp-cost');const roiText=document.getElementById('calc-roi');const calculateSavings=()=>{const area=parseFloat(houseAreaInput.value);const source=currentHeatSource.value;houseAreaValue.textContent=area;const rates={'electric':480,'gas':310,'coal':220};const hpRate=135;const currentRate=rates[source]||310;const currentAnnualCost=Math.round(area*currentRate);const hpAnnualCost=Math.round(area*hpRate);const annualSavings=currentAnnualCost-hpAnnualCost;const netInvestment=130000;const roiYears=annualSavings>0?(netInvestment/annualSavings).toFixed(1):'N/A';const formatCZK=(val)=>{return new Intl.NumberFormat('cs-CZ',{style:'currency',currency:'CZK',maximumFractionDigits:0}).format(val);};annualSavingsText.textContent=formatCZK(annualSavings);currentCostText.textContent=formatCZK(currentAnnualCost);hpCostText.textContent=formatCZK(hpAnnualCost);if(annualSavings>0){roiText.textContent=`${roiYears}let`;}else{roiText.textContent='Bez úspory';}};if(houseAreaInput&&currentHeatSource){houseAreaInput.addEventListener('input',calculateSavings);currentHeatSource.addEventListener('change',calculateSavings);calculateSavings();}const filterButtons=document.querySelectorAll('.filter-btn');const serviceCards=document.querySelectorAll('.service-card');filterButtons.forEach(button=>{button.addEventListener('click',()=>{filterButtons.forEach(btn=>btn.classList.remove('active'));button.classList.add('active');const filterValue=button.getAttribute('data-filter');serviceCards.forEach(card=>{const category=card.getAttribute('data-category');if(filterValue==='all'||category===filterValue){card.classList.remove('hide');card.classList.add('show');}else{card.classList.remove('show');card.classList.add('hide');}});});});const faqQuestions=document.querySelectorAll('.faq-question');faqQuestions.forEach(question=>{question.addEventListener('click',()=>{const answer=question.nextElementSibling;const isOpen=question.getAttribute('aria-expanded')==='true';faqQuestions.forEach(q=>{if(q!==question){q.setAttribute('aria-expanded','false');q.nextElementSibling.style.maxHeight=null;}});if(isOpen){question.setAttribute('aria-expanded','false');answer.style.maxHeight=null;}else{question.setAttribute('aria-expanded','true');answer.style.maxHeight=answer.scrollHeight+'px';}});question.addEventListener('keydown',(e)=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();question.click();}});});const track=document.getElementById('carousel-track');const slides=Array.from(track?track.children:[]);const nextBtn=document.getElementById('carousel-next');const prevBtn=document.getElementById('carousel-prev');const dotsContainer=document.getElementById('carousel-dots');let currentIndex=0;let autoPlayInterval;if(track&&slides.length>0){slides.forEach((_,idx)=>{const dot=document.createElement('button');dot.classList.add('carousel-dot');if(idx===0)dot.classList.add('active');dot.setAttribute('aria-label',`Přejít na recenzi ${idx+1}`);dotsContainer.appendChild(dot);});const dots=Array.from(dotsContainer.children);const moveToSlide=(index)=>{if(index<0)index=slides.length-1;if(index>=slides.length)index=0;track.style.transform=`translateX(-${index*100}%)`;dots[currentIndex].classList.remove('active');dots[index].classList.add('active');currentIndex=index;};nextBtn.addEventListener('click',()=>{moveToSlide(currentIndex+1);resetAutoplay();});prevBtn.addEventListener('click',()=>{moveToSlide(currentIndex-1);resetAutoplay();});dots.forEach((dot,idx)=>{dot.addEventListener('click',()=>{moveToSlide(idx);resetAutoplay();});});const startAutoplay=()=>{autoPlayInterval=setInterval(()=>{moveToSlide(currentIndex+1);},6000);};const resetAutoplay=()=>{clearInterval(autoPlayInterval);startAutoplay();};startAutoplay();let startX=0;let isSwiping=false;track.addEventListener('touchstart',(e)=>{startX=e.touches[0].clientX;isSwiping=true;clearInterval(autoPlayInterval);},{passive:true});track.addEventListener('touchmove',(e)=>{if(!isSwiping)return;const diffX=e.touches[0].clientX-startX;if(Math.abs(diffX)>50){if(diffX>0){moveToSlide(currentIndex-1);}else{moveToSlide(currentIndex+1);}isSwiping=false;}},{passive:true});track.addEventListener('touchend',()=>{isSwiping=false;startAutoplay();});}const contactForm=document.getElementById('contact-form');const formInputs=contactForm?contactForm.querySelectorAll('.form-input'):[];const statusMsg=document.getElementById('form-status');const validateInput=(input)=>{let isValid=true;const value=input.value.trim();if(input.hasAttribute('required')&&value===''){isValid=false;}else if(input.type==='email'&&value!==''){const emailRegex=/^[^\s@]+@[^\s@]+\.[^\s@]+$/;isValid=!emailRegex.test(value)?false:true;}else if(input.id==='form-phone'&&value!==''){const phoneRegex=/^(\+420)?\s*[1-9][0-9]{2}\s*[0-9]{3}\s*[0-9]{3}$/;isValid=!phoneRegex.test(value)?false:true;}if(!isValid){input.classList.add('invalid');input.setAttribute('aria-invalid','true');}else{input.classList.remove('invalid');input.setAttribute('aria-invalid','false');}return isValid;};formInputs.forEach(input=>{input.addEventListener('input',()=>{validateInput(input);});input.addEventListener('blur',()=>{validateInput(input);});});if(contactForm){contactForm.addEventListener('submit',(e)=>{e.preventDefault();let isFormValid=true;formInputs.forEach(input=>{if(!validateInput(input)){isFormValid=false;}});if(isFormValid){const submitBtn=contactForm.querySelector('button[type="submit"]');const originalText=submitBtn.textContent;submitBtn.disabled=true;submitBtn.textContent='Odesílám...';setTimeout(()=>{statusMsg.textContent='Děkujeme!Vaše zpráva byla úspěšně odeslána. Brzy se vám ozveme.';statusMsg.className='form-status success';contactForm.reset();formInputs.forEach(input=>{input.classList.remove('invalid');input.removeAttribute('aria-invalid');});submitBtn.disabled=false;submitBtn.textContent=originalText;statusMsg.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>{statusMsg.style.display='none';},8000);},1500);}else{const firstInvalid=contactForm.querySelector('.invalid');if(firstInvalid)firstInvalid.focus();}});}});